import { motion, AnimatePresence } from 'framer-motion';
import React, { useEffect, useState, useMemo } from 'react';
import Map, { Marker as MapMarker, Source, Layer, Popup as MapPopup } from 'react-map-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import {
  Truck,
  AlertTriangle,
  Cloud,
  Gauge,
  ArrowRight,
  Route,
  Shield,
  Zap,
  MapPin,
  Sun,
  CloudRain,
  CloudSnow,
  Package,
  Activity,
  Plus,
  Edit2,
  Trash2,
  X,
  Save,
} from 'lucide-react';
import axios from 'axios';
import './App.css';

const weatherLabel = (w) => {
  if (w === 0) return 'Clear';
  if (w === 1) return 'Rainy';
  return 'Stormy';
};

const getRiskColor = (level) => {
  if (level === 'High') return 'bg-rose-500 shadow-rose-500/50';
  if (level === 'Medium') return 'bg-amber-500 shadow-amber-500/50';
  return 'bg-emerald-500 shadow-emerald-500/50';
};


// ΓöÇΓöÇΓöÇ Animated counter ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const AnimatedNumber = ({ value, suffix = '' }) => (
  <motion.span
    key={value}
    initial={{ opacity: 0, y: 10 }}
    animate={{ opacity: 1, y: 0 }}
    transition={{ type: 'spring', stiffness: 200, damping: 20 }}
    className="tabular-nums"
  >
    {value}{suffix}
  </motion.span>
);

// ΓöÇΓöÇΓöÇ Main Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function App() {
  const [deliveries, setDeliveries] = useState([]);
  const [routeLine, setRouteLine] = useState(null);
  const [selectedStop, setSelectedStop] = useState(null);
  
  // 3D format routing using OSRM directly to render lines correctly over 3D pitched map
  useEffect(() => {
    if (optimizedRoute && optimizedRoute.features && optimizedRoute.features.length > 0) {
      const getRoute = async () => {
        try {
          const coords = optimizedRoute.features.map(f => `${f.geometry.coordinates[0]},${f.geometry.coordinates[1]}`).join(';');
          const url = `https://router.project-osrm.org/route/v1/driving/${coords}?geometries=geojson&overview=full`;
          const res = await fetch(url);
          const data = await res.json();
          if (data.routes && data.routes[0]) {
            setRouteLine({
              type: 'Feature',
              properties: {},
              geometry: data.routes[0].geometry
            });
          }
        } catch (e) {
          console.error('OSRM fetch error:', e);
        }
      };
      getRoute();
    } else {
      setRouteLine(null);
    }
  }, [optimizedRoute]);

  const [optimizedRoute, setOptimizedRoute] = useState(null);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [uploadedFileName, setUploadedFileName] = useState('');

  const handleOptimize = async () => {
    if (deliveries.length === 0) {
      alert('Please upload a CSV file first!');
      return;
    }

    setLoading(true);
    try {
      const payload = { deliveries };
      const response = await axios.post('http://127.0.0.1:8000/optimize_route', payload);
      setOptimizedRoute(response.data.optimized_route);
    } catch (error) {
      console.error('Optimization failed:', error);
      alert('Optimization service unavailable. Ensure backend is running.');
    } finally {
      setLoading(false);
    }
  };

  // ΓöÇΓöÇ CSV Upload Handler ΓöÇΓöÇ
  const handleFileUpload = async (event) => {
    const file = event.target.files[0];
    if (!file) return;

    if (!file.name.endsWith('.csv')) {
      alert('Please upload a CSV file');
      return;
    }

    setLoading(true);
    setUploadedFileName(file.name);

    try {
      const formData = new FormData();
      formData.append('file', file);

      const response = await axios.post('http://127.0.0.1:8000/upload_csv', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });

      if (response.data.error) {
        alert(`Error: ${response.data.error}`);
        setDeliveries([]);
        setOptimizedRoute(null);
      } else {
        // Set deliveries from CSV
        setDeliveries(response.data.deliveries.map(d => ({
          id: d.id,
          distance: d.distance,
          traffic_level: d.traffic_level,
          delivery_time: d.delivery_time,
          weather_condition: d.weather_condition,
          lat: d.lat,
          lng: d.lng,
          status: 'Pending'
        })));

        // Set optimized route
        setOptimizedRoute(response.data.optimized_route);

        alert(`Γ£à Successfully loaded ${response.data.total_deliveries} deliveries and calculated optimized route!`);
      }
    } catch (error) {
      console.error('Upload failed:', error);
      alert('Failed to upload CSV. Please check the file format.');
      setDeliveries([]);
      setOptimizedRoute(null);
    } finally {
      setLoading(false);
    }
  };

  const handleClearData = () => {
    if (window.confirm('Clear all delivery data and start fresh?')) {
      setDeliveries([]);
      setOptimizedRoute(null);
      setUploadedFileName('');
    }
  };

  // ΓöÇΓöÇ Derived stats ΓöÇΓöÇ
  const stats = useMemo(() => {
    if (!optimizedRoute || !optimizedRoute.features) {
      return { totalStops: deliveries.length, highRisk: 0, avgProb: 0, optimized: false };
    }
    const high = optimizedRoute.features.filter((s) => s.properties.risk_level === 'High').length;
    const avgP = optimizedRoute.features.reduce((a, s) => a + s.properties.risk_probability, 0) / optimizedRoute.features.length;
    return { totalStops: optimizedRoute.features.length, highRisk: high, avgProb: (avgP * 100).toFixed(1), optimized: true };
  }, [optimizedRoute, deliveries]);

  return (
    <div className="flex h-screen overflow-hidden relative">
      {/* Animated Background */}
      <div className="app-bg" />

      {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ SIDEBAR ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <aside className="sidebar w-64 flex flex-col shrink-0">
        {/* Logo */}
        <div className="px-6 py-6 border-b border-white/5">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-indigo-500 to-violet-600 flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <Truck size={18} className="text-white" />
            </div>
            <div>
              <h1 className="sidebar-logo text-lg font-bold tracking-tight">RouteOptimizer</h1>
              <p className="text-[11px] text-slate-500 font-medium tracking-wide">AI-POWERED OPTIMIZATION</p>
            </div>
          </div>
        </div>

        {/* CSV Upload Section */}
        <div className="flex-1 px-4 py-5">
          <div className="mb-4">
            <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3">Data Input</h3>
            <label className="block">
              <input
                type="file"
                accept=".csv"
                onChange={handleFileUpload}
                className="hidden"
                id="csv-upload"
              />
              <div className="cursor-pointer bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-500 hover:to-violet-500 transition-all p-4 rounded-xl text-center group">
                <Package size={32} className="mx-auto mb-2 text-white group-hover:scale-110 transition-transform" />
                <p className="text-white font-semibold text-sm">Upload CSV File</p>
                <p className="text-indigo-100 text-xs mt-1">Click to select file</p>
              </div>
            </label>
          </div>

          {uploadedFileName && (
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              className="bg-slate-800/50 border border-slate-700 rounded-lg p-3 mb-4"
            >
              <p className="text-xs text-slate-400 mb-1">Loaded File:</p>
              <p className="text-sm text-white font-medium truncate">{uploadedFileName}</p>
              <p className="text-xs text-emerald-400 mt-1">Γ£ô {deliveries.length} deliveries loaded</p>
            </motion.div>
          )}

          {deliveries.length > 0 && (
            <button
              onClick={handleClearData}
              className="w-full bg-slate-700 hover:bg-rose-600 text-white px-4 py-2.5 rounded-lg text-sm font-medium transition-colors flex items-center justify-center gap-2"
            >
              <Trash2 size={16} />
              Clear Data
            </button>
          )}

          <div className="mt-6 p-4 bg-slate-800/30 rounded-lg border border-slate-700/50">
            <h4 className="text-xs font-semibold text-slate-300 mb-2">Required CSV Columns:</h4>
            <ul className="text-[10px] text-slate-500 space-y-1">
              <li>ΓÇó distance (km)</li>
              <li>ΓÇó traffic_level (1-5)</li>
              <li>ΓÇó delivery_time (min)</li>
              <li>ΓÇó weather_condition (0-2)</li>
              <li>ΓÇó lat (latitude)</li>
              <li>ΓÇó lng (longitude)</li>
            </ul>
          </div>
        </div>

        {/* System Status */}
        <div className="px-4 py-4">
          <div className="system-status">
            <div className="flex items-center gap-2 mb-3">
              <div className="status-dot" />
              <span className="text-xs font-semibold text-slate-300">System Online</span>
            </div>
            <div className="space-y-2 text-[11px] text-slate-500">
              <div className="flex justify-between">
                <span>ML Model</span>
                <span className="text-indigo-400 font-medium">v1.0 Active</span>
              </div>
              <div className="flex justify-between">
                <span>GA Optimizer</span>
                <span className="text-emerald-400 font-medium">Ready</span>
              </div>
              <div className="flex justify-between">
                <span>Backend</span>
                <span className="text-emerald-400 font-medium">Connected</span>
              </div>
            </div>
          </div>
        </div>
      </aside>

      {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ MAIN CONTENT ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <main className="flex-1 flex flex-col overflow-hidden relative z-10">
        {/* Header */}
        <header className="app-header h-16 flex items-center justify-between px-6 shrink-0">
          <div>
            <h2 className="text-base font-semibold text-white">
              Operations Dashboard
            </h2>
            <p className="text-xs text-slate-500 mt-0.5">Upload CSV & calculate optimized route</p>
          </div>

          <button
            id="optimize-btn"
            onClick={handleOptimize}
            disabled={loading || deliveries.length === 0}
            className="optimize-btn flex items-center gap-2.5 px-5 py-2.5 rounded-xl text-white text-sm font-semibold"
          >
            {loading ? (
              <>
                <span className="loading-spinner" />
                OptimizingΓÇª
              </>
            ) : (
              <>
                <Route size={16} />
                Calculate Optimal Route
                <ArrowRight size={14} />
              </>
            )}
          </button>
        </header>

        {/* Content */}
        <div className="flex-1 overflow-auto p-5 custom-scrollbar">
          {/* ΓöÇΓöÇ Stat Cards ΓöÇΓöÇ */}
          <div className="grid grid-cols-4 gap-4 mb-5">
            {[
              {
                label: 'Total Stops',
                value: stats.totalStops,
                icon: MapPin,
                color: 'from-indigo-500/20 to-indigo-500/5',
                iconBg: 'bg-indigo-500/15 text-indigo-400',
              },
              {
                label: 'High Risk',
                value: stats.highRisk,
                icon: AlertTriangle,
                color: 'from-rose-500/20 to-rose-500/5',
                iconBg: 'bg-rose-500/15 text-rose-400',
              },
              {
                label: 'Avg Confidence',
                value: stats.optimized ? stats.avgProb : 'ΓÇö',
                suffix: stats.optimized ? '%' : '',
                icon: Shield,
                color: 'from-emerald-500/20 to-emerald-500/5',
                iconBg: 'bg-emerald-500/15 text-emerald-400',
              },
              {
                label: 'Status',
                value: stats.optimized ? 'Optimized' : 'Pending',
                icon: Zap,
                color: stats.optimized
                  ? 'from-violet-500/20 to-violet-500/5'
                  : 'from-slate-500/20 to-slate-500/5',
                iconBg: stats.optimized
                  ? 'bg-violet-500/15 text-violet-400'
                  : 'bg-slate-500/15 text-slate-400',
              },
            ].map((stat, idx) => {
              const Icon = stat.icon;
              return (
                <motion.div
                  key={stat.label}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: idx * 0.08, type: 'spring', stiffness: 180, damping: 22 }}
                  className="stat-card"
                >
                  <div className={`absolute inset-0 bg-gradient-to-br ${stat.color} rounded-2xl pointer-events-none`} />
                  <div className="relative flex items-start justify-between">
                    <div>
                      <p className="text-[11px] text-slate-500 font-medium uppercase tracking-wider mb-1.5">{stat.label}</p>
                      <p className="text-2xl font-bold text-white">
                        <AnimatedNumber value={stat.value} suffix={stat.suffix || ''} />
                      </p>
                    </div>
                    <div className={`stat-icon ${stat.iconBg}`}>
                      <Icon size={20} />
                    </div>
                  </div>
                </motion.div>
              );
            })}
          </div>

          {/* ΓöÇΓöÇ Map + Risk Panel ΓöÇΓöÇ */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-5" style={{ height: 'calc(100vh - 240px)' }}>
            {/* Map */}
            <div className="lg:col-span-2 map-panel rounded-2xl flex flex-col relative">
              {/* Map Legend */}
              <div className="absolute top-4 left-4 z-[1000] map-legend px-4 py-3">
                <h3 className="text-xs font-semibold text-slate-200 mb-2 flex items-center gap-1.5">
                  <Activity size={12} className="text-indigo-400" />
                  Live Route Map
                </h3>
                <div className="flex items-center gap-3 text-[10px] text-slate-400">
                  <span className="flex items-center gap-1.5"><span className="w-2 h-2 rounded-full bg-emerald-400" /> Low</span>
                  <span className="flex items-center gap-1.5"><span className="w-2 h-2 rounded-full bg-amber-400" /> Medium</span>
                  <span className="flex items-center gap-1.5"><span className="w-2 h-2 rounded-full bg-rose-400" /> High</span>
                  <span className="flex items-center gap-1.5"><span className="w-2 h-2 rounded-full bg-violet-400" /> Depot</span>
                </div>
              </div>

              <div className="flex-1 min-h-0 rounded-2xl overflow-hidden">
                <Map
                  initialViewState={{
                    longitude: 77.5946,
                    latitude: 12.9716,
                    zoom: 12.5,
                    pitch: 60,
                    bearing: -20
                  }}
                  mapStyle="https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json"
                  style={{ width: '100%', height: '100%' }}
                >
                  {routeLine && (
                    <Source type="geojson" data={routeLine}>
                      <Layer 
                        id="route-line" 
                        type="line" 
                        paint={{
                          'line-color': '#6366f1',
                          'line-width': 4,
                          'line-opacity': 0.8
                        }} 
                      />
                    </Source>
                  )}

                  {(optimizedRoute ? optimizedRoute.features : deliveries).map((item, idx) => {
                    const stop = optimizedRoute ? item.properties : item;
                    const lat = optimizedRoute ? item.geometry.coordinates[1] : item.lat;
                    const lng = optimizedRoute ? item.geometry.coordinates[0] : item.lng;
                    const data = stop.details || stop;
                    const risk = stop.risk_level || 'Pending';
                    const isDepot = (stop.id || stop.stop_id) === 1;

                    return (
                      <MapMarker 
                        key={idx} 
                        longitude={lng} 
                        latitude={lat}
                        anchor="bottom"
                        onClick={(e) => {
                          e.originalEvent.stopPropagation();
                          setSelectedStop({ stop, data, lat, lng, risk });
                        }}
                      >
                        {isDepot ? (
                          <div className="w-8 h-8 rounded-full bg-violet-600 border-2 border-white flex items-center justify-center shadow-lg shadow-violet-600/50 cursor-pointer hover:scale-110 transition-transform">
                            <Activity size={16} className="text-white" />
                          </div>
                        ) : (
                          <div className={`w-8 h-8 rounded-full border-2 border-white flex items-center justify-center shadow-lg cursor-pointer hover:scale-110 transition-transform ${getRiskColor(risk)}`}>
                            <span className="text-white text-xs font-bold">{stop.id || stop.stop_id}</span>
                          </div>
                        )}
                      </MapMarker>
                    );
                  })}
                  
                  {selectedStop && (
                    <MapPopup
                      longitude={selectedStop.lng}
                      latitude={selectedStop.lat}
                      anchor="top"
                      closeButton={true}
                      closeOnClick={false}
                      onClose={() => setSelectedStop(null)}
                      className="custom-map-popup"
                    >
                      <div className="p-2 min-w-[160px]">
                        <div className="flex items-center justify-between border-b border-gray-100 pb-2 mb-2">
                          <strong className="text-[13px] text-gray-800 flex items-center gap-1.5">
                            {(selectedStop.stop.id || selectedStop.stop.stop_id) === 1 ? (
                              <><Activity size={14} className="text-violet-600" /> Depot</>
                            ) : (
                              <><Package size={14} className="text-indigo-600" /> Stop #{selectedStop.stop.id || selectedStop.stop.stop_id}</>
                            )}
                          </strong>
                          {(selectedStop.stop.id || selectedStop.stop.stop_id) !== 1 && (
                            <span className={`text-[10px] font-bold px-2 py-0.5 rounded-md ${
                              selectedStop.risk === 'High' ? 'bg-rose-100 text-rose-700' :
                              selectedStop.risk === 'Medium' ? 'bg-amber-100 text-amber-700' :
                              'bg-emerald-100 text-emerald-700'
                            }`}>
                              {selectedStop.risk}
                            </span>
                          )}
                        </div>
                        
                        {(selectedStop.stop.id || selectedStop.stop.stop_id) !== 1 && (
                            <div className="space-y-1.5 text-[11px] text-gray-600">
                              <div className="flex items-center justify-between">
                                <span className="flex items-center gap-1"><Shield size={12} className="text-gray-400"/> Confidence:</span>
                                <strong className="font-medium">{(selectedStop.stop.risk_probability * 100 || selectedStop.data.risk_probability * 100 || 0).toFixed(1)}%</strong>
                              </div>
                              <div className="flex items-center justify-between">
                                <span className="flex items-center gap-1"><Truck size={12} className="text-gray-400"/> Traffic:</span>
                                <strong className="font-medium">{selectedStop.stop.traffic || selectedStop.data.traffic_level}/5</strong>
                              </div>
                              <div className="flex items-center justify-between">
                                <span className="flex items-center gap-1"><Cloud size={12} className="text-gray-400"/> Weather:</span>
                                <strong className="font-medium flex items-center gap-1">
                                  {weatherLabel(selectedStop.stop.weather ?? selectedStop.data.weather_condition)}
                                </strong>
                              </div>
                              <div className="flex items-center justify-between">
                                <span className="flex items-center gap-1"><MapPin size={12} className="text-gray-400"/> Distance:</span>
                                <strong className="font-medium">{selectedStop.stop.distance || selectedStop.data.distance} km</strong>
                              </div>
                            </div>
                        )}
                        {(selectedStop.stop.id || selectedStop.stop.stop_id) === 1 && (
                          <p className="text-[11px] text-gray-500 text-center italic mt-1">Route starting point</p>
                        )}
                      </div>
                    </MapPopup>
                  )}
                </Map>
              </div>
            </div>

            {/* ΓöÇΓöÇ Right Panel: Risk Analysis ΓöÇΓöÇ */}
            <div className="risk-panel rounded-2xl flex flex-col overflow-hidden">
              <div className="px-5 py-4 border-b border-white/5 shrink-0">
                <h3 className="text-sm font-semibold text-white flex items-center gap-2">
                  <AlertTriangle size={16} className="text-amber-400" />
                  Risk Analysis
                </h3>
                <p className="text-[11px] text-slate-500 mt-0.5">AI-predicted delivery risk levels</p>
              </div>

              <div className="flex-1 overflow-y-auto px-4 py-4 space-y-3 custom-scrollbar">
                <AnimatePresence mode="wait">
                  {!optimizedRoute ? (
                    <motion.div
                      key="empty"
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      exit={{ opacity: 0 }}
                      className="empty-state h-full"
                    >
                      <div className="empty-state-icon">
                        <Route size={28} />
                      </div>
                      <p className="text-sm font-medium text-slate-400">No route optimized yet</p>
                      <p className="text-xs text-slate-600 text-center max-w-[200px]">
                        Click <b>"Calculate Optimal Route"</b> to run AI risk prediction and genetic algorithm optimization.
                      </p>
                    </motion.div>
                  ) : (
                    optimizedRoute.features.map((item, idx) => {
                      const stop = item.properties;
                      const riskLower = (stop.risk_level || 'low').toLowerCase();
                      const probPercent = (stop.risk_probability * 100).toFixed(1);

                      const probColor =
                        riskLower === 'high'
                          ? 'bg-rose-500'
                          : riskLower === 'medium'
                            ? 'bg-amber-500'
                            : 'bg-emerald-500';

                      return (
                        <motion.div
                          key={`stop-${idx}`}
                          initial={{ opacity: 0, x: 20 }}
                          animate={{ opacity: 1, x: 0 }}
                          transition={{ delay: idx * 0.07, type: 'spring', stiffness: 200, damping: 24 }}
                          className={`risk-card risk-${riskLower}`}
                        >
                          {/* Header Row */}
                          <div className="flex items-center justify-between mb-3">
                            <div className="flex items-center gap-2">
                              <span className="text-xs font-bold text-slate-300 bg-slate-800/80 px-2.5 py-1 rounded-lg">
                                #{idx + 1}
                              </span>
                              <span className="text-xs text-slate-500">Stop {stop.stop_id}</span>
                            </div>
                            <span className={`risk-badge risk-badge-${riskLower}`}>
                              {stop.risk_level}
                            </span>
                          </div>

                          {/* Details Grid */}
                          <div className="grid grid-cols-3 gap-3 text-xs">
                            <div className="flex flex-col items-center gap-1 py-2 rounded-lg bg-slate-900/40">
                              <Truck size={13} className="text-slate-400" />
                              <span className="text-slate-500">Traffic</span>
                              <span className="text-white font-semibold">{stop.traffic}/5</span>
                            </div>
                            <div className="flex flex-col items-center gap-1 py-2 rounded-lg bg-slate-900/40">
                              <WeatherIcon condition={stop.weather} size={13} />
                              <span className="text-slate-500">Weather</span>
                              <span className="text-white font-semibold">{weatherLabel(stop.weather)}</span>
                            </div>
                            <div className="flex flex-col items-center gap-1 py-2 rounded-lg bg-slate-900/40">
                              <MapPin size={13} className="text-slate-400" />
                              <span className="text-slate-500">Dist</span>
                              <span className="text-white font-semibold">{stop.distance}km</span>
                            </div>
                          </div>

                          {/* Probability Bar */}
                          <div className="mt-3">
                            <div className="flex justify-between items-center text-[10px]">
                              <span className="text-slate-500">Confidence</span>
                              <span className="text-slate-400 font-medium">{probPercent}%</span>
                            </div>
                            <div className="prob-bar-track">
                              <motion.div
                                initial={{ width: 0 }}
                                animate={{ width: `${probPercent}%` }}
                                transition={{ delay: idx * 0.07 + 0.3, duration: 0.6, ease: 'easeOut' }}
                                className={`prob-bar-fill ${probColor}`}
                              />
                            </div>
                          </div>
                        </motion.div>
                      );
                    })
                  )}
                </AnimatePresence>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

export default App;
